function expandWikiShorthand(input:string){
  return input.replace(/\b(\d+(?:\.\d+)?)\s*([kKmM])\b/g,(_,n,u)=>String(Math.round(Number(n)*(String(u).toLowerCase()==='m'?1_000_000:1_000))))
    .replace(/\b(\d+(?:\.\d+)?)\s*(?:tons?|tonnes?|t)\b/gi,(_,n)=>String(Math.round(Number(n)*1000)));
}
function rowIsHistorical(r:WikiRecord){return wikiRecordIsHistorical(r);}
function rowAsOf(r:WikiRecord){const raw=r.qualifiers?.asOf??r.data?.asOf??null;const t=raw?new Date(String(raw)).getTime():0;return Number.isFinite(t)?t:0;}
function preferredRows(k:Cache,rows:WikiRecord[]){return [...rows].map(r=>effectiveRecord(k,r)).sort((a,b)=>Number(Boolean(b.qualifiers?.current))-Number(Boolean(a.qualifiers?.current))||Number(rowIsHistorical(a))-Number(rowIsHistorical(b))||rowAsOf(b)-rowAsOf(a));}
function resolveAnyEntity(k:Cache,q:string){
  const gm=groups(k.records),out:{rows:WikiRecord[];score:number}[]=[];for(const rows of gm.values()){const s=Math.max(...rows.map(r=>score(r,q)));if(s>=45)out.push({rows,score:s});}out.sort((a,b)=>b.score-a.score);return out;
}
/** Distinct imports about one hull are evidence sources, not different ships.
 * Keep cross-kind disambiguation for generic questions, but prefer the actual
 * playable ship when someone asks about cargo, crew, speed, armor, etc. */
function ambiguityOptions(k:Cache,q:string){
 const ranked=resolveAnyEntity(k,q).filter(x=>x.score>=650).slice(0,8);
 if(ranked.length<2||ranked[0].score-ranked[1].score>28)return [] as any[];
 const exact=ranked.some(x=>x.rows.some(r=>normalize(r.name)===normalize(q)));if(exact)return [];
 const shipQuestion=/\b(?:ship|hull|vessel|boat|hold|cargo|carry|capacity|weight|speed|armor|armour|crew|guns|maneuver|durability)\b/i.test(q);
 const mentionedShip=ranked.find(x=>x.rows.some(r=>r.kind==='ship'&&mentionsExactEntity(q,r.name)));
 if(shipQuestion&&mentionedShip)return [];
 const result:any[]=[];const seen=new Set<string>();
 for(const x of ranked){const name=normalize(x.rows[0].name);if(seen.has(name))continue;seen.add(name);result.push({entityKey:x.rows[0].entity_key,name:x.rows[0].name,kind:x.rows[0].kind,score:x.score});if(result.length===4)break;}
 // A single game entity can have historical, builder, and technical records.
 return result.length<2?[]:result;
}
/** Match a complete name inside a question, not a fuzzy token in an unrelated name. */
function mentionsExactEntity(question:string,name:string){
 const q=` ${normalize(question)} `,n=normalize(name);
 return Boolean(n&&q.includes(` ${n} `));
}
