function articleFactLabel(path:string){const special:Record<string,string>={'portBattle':'Port battle','materials':'Materials','baseMaterials':'Base materials','stats':'Stats','profile':'Source profile'};if(path.startsWith('stats.')&&['hold','durability','armor','speed','maneuverability','crew','guns'].includes(path.slice(6)))return fieldLabel(path);return path.split('.').map(part=>special[part]??part.replace(/([a-z])([A-Z])/g,'$1 $2').replaceAll('_',' ').replace(/^./,c=>c.toUpperCase())).join(' · ');}
