  const hits=resolveAnyEntity(k,q).filter(x=>x.score>=520).slice(0,12);const shipHit=hits.find(x=>x.rows[0].kind==='ship'||x.rows[0].kind==='ship_builder_hull');const items=hits.filter(x=>x.rows[0].kind==='build_item').map(x=>preferredRows(k,x.rows)[0]).filter(Boolean);const guides=bestTextRecords(k,['guide'],q,2);
