function compareQuestionEntityNames(k:Cache,q:string){const ranked=resolveAnyEntity(k,q).filter(x=>x.score>=560);if(ranked.length>=2){const topKind=ranked[0].rows[0].kind;const same=ranked.filter(x=>x.rows[0].kind===topKind).slice(0,5);if(same.length>=2)return same.map(x=>x.rows[0].name);}const cleaned=q.replace(/^.*?compare\s+/i,'').replace(/\?$/,'');const pieces=cleaned.split(/\s+(?:vs\.?|versus|and|with)\s+|\s*,\s*/i).map(x=>x.trim()).filter(x=>x.length>1);return pieces.slice(0,5);}
