 app.get("/v1/wiki/summary",async(req:any,reply:any)=>{if(!(await requireMember(req,reply))?.member)return;const k=await knowledge(guildId);const counts:Record<string,number>={};for(const g of groups(k.records).values())counts[g[0].kind]=(counts[g[0].kind]??0)+1;const sources=await many<any>(`SELECT source_id,name,source_kind,file_name,description,updated_at FROM wiki_sources ORDER BY name`);const unanswered=await oneOrNone<any>(`SELECT COUNT(*)::int AS count FROM wiki_question_log WHERE guild_id=$1 AND answered=FALSE`,[guildId]);const conflicts=conflictInventory(k);return {entities:Object.values(counts).reduce((a,b)=>a+b,0),records:k.records.length,counts,sources:sources.length,activeCorrections:k.overrides.length,unanswered:Number(unanswered?.count??0),conflictFields:conflicts.length,conflictEntities:new Set(conflicts.map(x=>x.entityKey)).size};});
