 app.get("/v1/wiki/search",async(req:any,reply:any)=>{if(!(await requireMember(req,reply))?.member)return;const raw=String(req.query?.q??"").trim();const actor=userId(req)||"anonymous",preferred=await getPreferredLanguage(guildId,actor),language=detectLanguage(raw,preferred),k=await knowledge(guildId);const candidateNames=k.records.map(r=>({name:r.name,s:score(r,raw)})).sort((a,b)=>b.s-a.s).slice(0,40).map(x=>x.name);const q=await canonicalizeMultilingualQuestion(await applyGuildLexicon(guildId,normalizeBOMQuery(raw),"wiki"),language,candidateNames);const ranked=k.records.map(r=>({r,s:textScore(r,q)})).filter(x=>x.s>=35).sort((a,b)=>b.s-a.s);const seen=new Set<string>(),results=[] as any[];for(const x of ranked){if(seen.has(x.r.entity_key))continue;seen.add(x.r.entity_key);results.push({entityKey:x.r.entity_key,kind:x.r.kind,name:x.r.name,aliases:x.r.aliases});if(results.length>=50)break;}return {results,language};});
